// El nombre de la clase debe coincidir con el nombre del archivo (HolaMundo.java)
public class HolaMundo {

    public static void main(String[] args) {
        // Imprimir un mensaje en la consola
        System.out.println("¡Hola! Estás dando tus primeros pasos en Java.");

        // Definir variables
        int numero1 = 10;
        int numero2 = 20;
        int suma = numero1 + numero2;

        // Mostrar el resultado
        System.out.println("La suma de " + numero1 + " y " + numero2 + " es: " + suma);
        
        // Un pequeño mensaje de ánimo
        System.out.println("¡Mucho éxito con tus proyectos de Ingeniería en Sistemas!");
    }
}